// The temporary exercise list (PLAN 1.7): every exercise in the shipped plans, generated by
// scripts/build-plan-exercises.ts. Replaced by the catalog in Session 2.
import list from '../../data/plan-exercises.json';
import type { PlanExercise } from '../lib/loadTypeRule';

export const PLAN_EXERCISES = list as PlanExercise[];

const BY_ID = new Map(PLAN_EXERCISES.map((e) => [e.id, e]));

export function planExercise(id: string): PlanExercise | undefined {
  return BY_ID.get(id);
}
